Which is the graph of \( y = g(-x) \)?

[asy]
unitsize(0.5 cm);

picture[] graf;
int i, n;

real func(real x) {
  real y;
  if (x >= -4 && x <= -1) {y = 2*x + 8;}
  if (x >= -1 && x <= 1) {y = -x^2 + 2;}
  if (x >= 1 && x <= 4) {y = -2*(x - 3);}
  return(y);
}

real funcb(real x) {
  return(-func(x));
}

real funcd(real x) {
  return(-func(-x));
}

real funce(real x) {
  return(func(-x));
}

for (n = 1; n <= 5; ++n) {
  graf[n] = new picture;
  for (i = -5; i <= 5; ++i) {
    draw(graf[n],(i,-5)--(i,5),gray(0.7));
